#!/bin/sh
# Generated by FWShift: AWS EC2 security groups for one VPC, created with the AWS CLI. Read the report first:
# what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                 prints the calls, makes none (no AWS access needed)
#   VPC_ID=vpc-... CHECK=1 sh THIS_FILE    sends every call with --dry-run: AWS checks the permissions
#   VPC_ID=vpc-... sh THIS_FILE            creates the groups and their rules
#
# AWS_OPTS adds options to every call, for example AWS_OPTS='--region eu-west-1 --profile prod'.
#
# The groups are created WITHOUT members: nothing changes for any traffic until they are attached. Attach each
# group to the network interfaces whose private addresses are listed after it (# attach ...): an interface gets
# every group whose list holds one of its addresses, and then no other groups. A group of the same name in the
# VPC stops the script before anything is created; a call AWS refuses stops it where it is (delete the groups
# it made with aws ec2 delete-security-group --group-id ... and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
CHECK="${CHECK:-}"
AWS_OPTS="${AWS_OPTS:-}"
if [ -z "$DRY_RUN" ]; then
  : "${VPC_ID:?set VPC_ID to the id of the VPC (vpc-...), or DRY_RUN=1 to print the calls}"
else
  VPC_ID="${VPC_ID:-vpc-DRYRUN}"
fi
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
show() { printf 'aws ec2' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; }
# change CALL ARGS...: a call that changes something
change() {
  if [ -n "$DRY_RUN" ]; then show "$@"; return 0; fi
  if [ -n "$CHECK" ]; then
    out=$(aws ec2 "$@" --dry-run $AWS_OPTS 2>&1)
    case "$out" in *DryRunOperation*) printf 'checked: %s\n' "$1" >&2; return 0 ;; esac
    fail "aws ec2 $1: $out"
  fi
  aws ec2 "$@" $AWS_OPTS >/dev/null || fail "aws ec2 $1"
}
# free NAME: stops the script when the VPC has a group of that name
free() {
  if [ -n "$DRY_RUN" ]; then return 0; fi
  found=$(aws ec2 describe-security-groups --filters "Name=vpc-id,Values=$VPC_ID" "Name=group-name,Values=$1" --query 'SecurityGroups[0].GroupId' --output text $AWS_OPTS) || fail "describe-security-groups: $found"
  [ "$found" = None ] || fail "a group named $1 exists in $VPC_ID already ($found); nothing was created"
}
# revoke GROUP PERMISSIONS: takes an outbound rule off a new group; a rule that is not there is fine
revoke() {
  out=$(aws ec2 revoke-security-group-egress --group-id "$1" --ip-permissions "$2" $AWS_OPTS 2>&1) && return 0
  case "$out" in *InvalidPermission.NotFound*|*InvalidParameterValue*) return 0 ;; esac
  fail "revoke-security-group-egress $1: $out"
}
# group NAME DESCRIPTION: creates a group without rules and prints its id
group() {
  if [ -n "$DRY_RUN" ]; then show create-security-group --group-name "$1" --description "$2" --vpc-id "$VPC_ID"; printf 'sg-dryrun-%s\n' "$1"; return 0; fi
  if [ -n "$CHECK" ]; then change create-security-group --group-name "$1" --description "$2" --vpc-id "$VPC_ID"; printf '%s\n' "$STAND_IN"; return 0; fi
  id=$(aws ec2 create-security-group --group-name "$1" --description "$2" --vpc-id "$VPC_ID" --tag-specifications '[{"ResourceType":"security-group","Tags":[{"Key":"fwshift","Value":"generated"}]}]' --query GroupId --output text $AWS_OPTS) || fail "create-security-group $1"
  aws ec2 wait security-group-exists --group-ids "$id" $AWS_OPTS || fail "group $id did not appear"
  # A new group allows everything outbound (IPv4, and IPv6 where the VPC has it): take that off, and make sure.
  revoke "$id" '[{"IpProtocol":"-1","IpRanges":[{"CidrIp":"0.0.0.0/0"}]}]'
  revoke "$id" '[{"IpProtocol":"-1","Ipv6Ranges":[{"CidrIpv6":"::/0"}]}]'
  left=$(aws ec2 describe-security-group-rules --filters "Name=group-id,Values=$id" --query 'length(SecurityGroupRules[?IsEgress])' --output text $AWS_OPTS) || fail "describe-security-group-rules $id"
  [ "$left" = 0 ] || fail "group $id still has $left outbound rules; it was not given any others"
  printf 'created %s %s\n' "$1" "$id" >&2
  printf '%s\n' "$id"
}
ingress() { perms=$(cat); change authorize-security-group-ingress --group-id "$1" --ip-permissions "$perms"; }
egress() { perms=$(cat); change authorize-security-group-egress --group-id "$1" --ip-permissions "$perms"; }
STAND_IN=""
if [ -z "$DRY_RUN" ] && [ -n "$CHECK" ]; then
  STAND_IN=$(aws ec2 describe-security-groups --filters "Name=vpc-id,Values=$VPC_ID" "Name=group-name,Values=default" --query 'SecurityGroups[0].GroupId' --output text $AWS_OPTS) || fail "no default group in $VPC_ID"
fi

# No group of these names may exist.
free 'fwshift-addresses'
free 'fwshift-Office-LAN'
free 'fwshift-DMZ-Servers'
free 'fwshift-addresses-ipv6'
free 'fwshift-V6-Servers-ipv6'
free 'fwshift-no-rules'

# The groups, each with the private addresses of the network interfaces it is for.
# attach fwshift-addresses: 0.0.0.0-10.9.255.255 10.11.0.0-10.20.0.15 10.20.1.0-255.255.255.255
G1=$(group 'fwshift-addresses' 'FWShift: for the interfaces of 0.0.0.0-10.9.255.255 10.11.0.0-10.20.0.15 10.20.1.0-255.255.255.255') || exit 1
# attach fwshift-Office-LAN: 10.10.0.0/16
G2=$(group 'fwshift-Office-LAN' 'FWShift: for the interfaces of 10.10.0.0/16') || exit 1
# attach fwshift-DMZ-Servers: 10.20.0.16-10.20.0.255
G3=$(group 'fwshift-DMZ-Servers' 'FWShift: for the interfaces of 10.20.0.16-10.20.0.255') || exit 1
# attach fwshift-addresses-ipv6: ::-2001:db8:1f:ffff:ffff:ffff:ffff:ffff 2001:db8:20:1::-2001:db8:bac:ffff:ffff:ffff:ffff:ffff 2001:db8:bae::-ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff
G4=$(group 'fwshift-addresses-ipv6' 'FWShift: for the interfaces of ::-2001:db8:1f:ffff:ffff:ffff:ffff:ffff 2001:db8:20:1::-2001:db8:bac:ffff:ffff:ffff:ffff:ffff 2001:db8:bae::-ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff') || exit 1
# attach fwshift-V6-Servers-ipv6: 2001:db8:20::/64
G5=$(group 'fwshift-V6-Servers-ipv6' 'FWShift: for the interfaces of 2001:db8:20::/64') || exit 1
# attach fwshift-no-rules: 2001:db8:bad::/48
G6=$(group 'fwshift-no-rules' 'FWShift: for the interfaces of 2001:db8:bad::/48') || exit 1

